PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?deathDate
WHERE {
  {
    dbr:The_Fatal_Mistake dbo:director ?director .
    ?director dbo:deathDate ?deathDate .
    BIND(dbr:The_Fatal_Mistake AS ?film)
  } UNION {
    <http://dbpedia.org/resource/The_Devil's_Hairpin> dbo:director ?director .
    ?director dbo:deathDate ?deathDate .
    BIND(<http://dbpedia.org/resource/The_Devil's_Hairpin> AS ?film)
  }
}
LIMIT 100

